 ap=argparse.ArgumentParser();ap.add_argument('--ledger',required=True);ap.add_argument('--source-map',required=True);ap.add_argument('--result',required=True);ap.add_argument('--freeze',required=True);ap.add_argument('--output',required=True);a=ap.parse_args();o=Path(a.output);assert not o.exists();L=json.loads(Path(a.ledger).read_text());S=json.loads(Path(a.source_map).read_text());R=json.loads(Path(a.result).read_text());F=json.loads(Path(a.freeze).read_text());req=L['required_fields'];cal=[r['id'] for r in L['families'] if all(r[k]==M for k in req)];real=sum(r['real_backend_rows']==M for r in L['families']);checks={'decision':R['decision']=='PASS_RETAINED_PROBABILISTIC_AUTOMATON_CALIBRATION_NOT_IDENTIFIABLE_SCOPED','families':len(L['families'])==5==R['family_count'],'real':real>=2 and R['real_backend_family_count']==real,'calibratable_zero':cal==[]==R['calibratable_families'],'all_invalid':R['invalid_family_count']==5,'no_estimate':L['production_estimate'] is None and not R['production_estimate_emitted'],'no_cross_family':not L['cross_family_substitution'] and not R['cross_family_substitution'],'corruptions':all(R['corruption_controls'].values()),'formal':R['formal_invocations']==1 and R['reruns']==0 and R['replacements']==0 and R['tuning']==0,'source_plan':h('PLAN.md')==F['sha256']['PLAN.md'],'source_map':h('SOURCE_MAP.json')==F['sha256']['SOURCE_MAP.json'],'source_ledger':h('LEDGER.json')==F['sha256']['LEDGER.json'],'source_analyze':h('analyze.py')==F['sha256']['analyze.py'],'source_audit':h('audit.py')==F['sha256']['audit.py']};z={'status':'PASS' if all(checks.values()) else 'FAIL','checks':checks,'result_sha256':h(a.result),'freeze_sha256':h(a.freeze)};o.write_text(json.dumps(z,indent=2,sort_keys=True)+'\n');print(json.dumps(z,indent=2,sort_keys=True));raise SystemExit(0 if z['status']=='PASS' else 1)
